import { getToken as fcmGetToken, onMessage } from "firebase/messaging";
import { initFirebase, messaging } from "./firebase";

let isInitialized = false;
let swRegistration = null;
let pendingListeners = [];


const BACKEND_URL = "https://dev-push-notification-backend.vercel.app";

export const getToken = async (apiKey) => {
  try {
    const res = await fetch(`${BACKEND_URL}/api/sdk/config`, {
      headers: { "x-api-key": apiKey },
    });

    const { firebaseConfig, vapidKey } = await res.json();

    if (!isInitialized) {
      initFirebase(firebaseConfig);
      isInitialized = true;
    }

    const swRegistration = await navigator.serviceWorker.register(
      "/dpn-sw.js",
    );

    const token = await fcmGetToken(messaging, {
      vapidKey,
      serviceWorkerRegistration: swRegistration,
    });
    if (!token) {
      console.error("Failed to get FCM token");
      return null;
    }

    const creditRes = await fetch(
      `${BACKEND_URL}/api/notification/get-fcm-tokken`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": apiKey,
        },
        body: JSON.stringify({ token }),
      },
    );

    const creditData = await creditRes.json();

    return creditData;
  } catch (err) {
    console.error("SDK Token Error:", err);
    return null;
  }
};

export const sendNotification = async ({
  apiKey,
  title,
  body,
  icon,
  fcmTokens,
  link,
}) => {
  try {
    const res = await fetch(
      `${BACKEND_URL}/api/notification/send-notification`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": apiKey,
        },
        body: JSON.stringify({ title, body, icon, fcmTokens, link }),
      },
    );

    const data = await res.json();
    return data;
  } catch (err) {
    console.error("SDK sendNotification error:", err);
    throw err;
  }
};

export const onMessageListener = (callback, apiKey) => {
  if (isInitialized) {
    return onMessage(messaging, callback);
  }
  pendingListeners.push({ callback, apiKey });
  return () => {
    pendingListeners = pendingListeners.filter((l) => l.callback !== callback);
  };
};

export const initMessaging = async (apiKey) => {
  if (isInitialized) return;

  const res = await fetch(`${BACKEND_URL}/api/sdk/config`, {
    headers: { "x-api-key": apiKey },
  });
  const { firebaseConfig, vapidKey } = await res.json();

  initFirebase(firebaseConfig);

  swRegistration = await navigator.serviceWorker.register(
    "/dpn-sw.js",
  );

  isInitialized = true;
  pendingListeners.forEach(({ callback }) => {
    onMessage(messaging, callback);
  });
  pendingListeners = [];
};
